 var face=_eyes(mood,30,L.iris,ol)+_mouth(mood,40.4,ol)+'<ellipse cx="19.8" cy="36.4" rx="3.2" ry="2" fill="#ff6f91" opacity=".32"/><ellipse cx="44.2" cy="36.4" rx="3.2" ry="2" fill="#ff6f91" opacity=".32"/>'+_feat(L.feat,ol,hc);
