function nextLesson(){for(var i=0;i<UN.length;i++){var u=UN[i],us=S.un[u.id]||{d:{}};for(var j=0;j<u.lessons.length;j++)if(!us.d[u.lessons[j].id])return{u:u,L:u.lessons[j],i:i}}return null}
