 mg.tiles.forEach(function(t,i){h+='<button data-m="'+i+'" class="'+(t.gone?'gone':'')+(mg.sel===i?' sel':'')+(mg.wrong===i?' wrong':'')+'">'+esc(t.s)+'</button>'});
